create extension if not exists pgcrypto;
create table public.players(id uuid primary key default gen_random_uuid(), display_name text not null, nickname text, created_at timestamptz default now());
create table public.trips(id uuid primary key default gen_random_uuid(), slug text unique not null, name text not null, start_date date, end_date date, location text, summary text, cover_image_path text, created_at timestamptz default now());
create table public.photos(id uuid primary key default gen_random_uuid(), trip_id uuid references public.trips on delete cascade, storage_path text not null, original_filename text, captured_at timestamptz, uploaded_by uuid references auth.users, created_at timestamptz default now());
create table public.competitions(id uuid primary key default gen_random_uuid(), trip_id uuid references public.trips on delete cascade, name text not null, competition_type text not null, priority int default 0);
create table public.competition_results(id uuid primary key default gen_random_uuid(), competition_id uuid references public.competitions on delete cascade, player_id uuid references public.players, position int, score numeric, score_label text);
alter table public.players enable row level security; alter table public.trips enable row level security; alter table public.photos enable row level security; alter table public.competitions enable row level security; alter table public.competition_results enable row level security;
create policy "public read players" on public.players for select using(true); create policy "public read trips" on public.trips for select using(true); create policy "public read photos" on public.photos for select using(true); create policy "public read competitions" on public.competitions for select using(true); create policy "public read results" on public.competition_results for select using(true);
create policy "auth insert photos" on public.photos for insert to authenticated with check(auth.uid()=uploaded_by);